#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Export a small IGC assembly subset to a Lean `Program` definition.

Only the line-oriented subset used by the stage-4 GEMM loop fixture is
parsed. Operands stay raw strings; decoding is a later stage.
"""

import argparse
import json
from pathlib import Path

HEADER = """-- SPDX-License-Identifier: Apache-2.0
-- Generated by Tools/parse_igc.py. Do not edit.
module

public import Intel.Syntax

@[expose] public section

namespace IntelGpu

def gemmLoop : Program :=
  { statements := [
"""

FOOTER = """  ] }

end IntelGpu
"""


def parse(text: str):
    stmts = []
    for raw in text.splitlines():
        line = raw.split("//", 1)[0].strip()
        if not line:
            continue
        if line.endswith(":"):
            stmts.append(("label", line[:-1]))
            continue
        parts = line.split()
        opcode = parts[0]
        operands = [p.rstrip(",") for p in parts[1:]]
        stmts.append(("instruction", opcode, operands))
    return stmts


def lean(stmts) -> str:
    out = [HEADER]
    for stmt in stmts:
        if stmt[0] == "label":
            out.append(f"    .label {json.dumps(stmt[1])},\n")
        else:
            operands = ", ".join(json.dumps(x) for x in stmt[2])
            out.append(f"    .instruction {json.dumps(stmt[1])} [{operands}],\n")
    out.append(FOOTER)
    return "".join(out)


def main():
    cli = argparse.ArgumentParser(description=__doc__)
    cli.add_argument("asm", type=Path)
    cli.add_argument("-o", "--output", type=Path, required=True)
    cli.add_argument("--check", action="store_true")
    args = cli.parse_args()
    text = lean(parse(args.asm.read_text()))
    if args.check:
        if not args.output.exists() or args.output.read_text() != text:
            raise SystemExit(f"{args.output} is stale")
        return
    args.output.write_text(text)


if __name__ == "__main__":
    main()
